var img;
var dome;
var sample;
var x, y;
var painting;
var z = -600;
var zvel = 30;

function preload(){
	img = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/brueghel2.jpg');
	painting = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/brueghel2.jpg');
}

function setup() {
	img.resize(0,windowHeight);
	painting.resize(0,windowHeight);
	//img.filter(BLUR,1);
	createCanvas(windowWidth, img.height, WEBGL);
	imageMode(CENTER);
	noCursor();
	dome = height/6;
	sample = PI*dome;
	x = 0;
	y = height;
}

function draw() {
	background(0);
	ambientLight(200);
	pointLight(100,100,100,width/2,-300,100);
	pointLight(100,100,100,-width/2,-300,100);
	if(frameCount>60){
		z+=zvel;
		zvel*=0.95;
	}
	if(z>250) {z-=zvel; zvel*=-1;}
	translate(0,0,z);	
	x = lerp(x, (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - width/2, 0.1);
	y = lerp(y, (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - height/2, 0.1);
	rotateY(1.2*x/width);
	rotateX(1.2*y/-height);
	image(img,0,0);
	translate(x,y,0);
  noStroke();
	let txt = painting.get(x+img.width/2-sample/2,y+img.height/2-dome, sample, 2*dome);
	texture(txt);
	rotateY(PI);
	let domeheight = (sample-PI*dome)/8;
	translate(0,0,domeheight);
	//sphere(dome);
	ellipsoid(dome, dome, dome/1.25,32,32);
	rotateX(PI/2);
	specularMaterial(171,141,63);
	translate(0,-dome/8-domeheight/2,0);
	cylinder(dome*1.05,(dome/4)-domeheight,32,1);
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) dome*=1.08;
	dome = lerp(dome, height/7, 0.15);
	sample = PI*dome;
	checkKeys();
}

function checkKeys(){
	if(keyIsDown(UP_ARROW)) zvel+=1;
	if(keyIsDown(DOWN_ARROW)) zvel-=1;
}
